const D = { density:.5, scale:1, energy:.6, speed:1, hue:210, swirl:.5, comb:.5, x:.5, y:.5, style:'paper marble', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, u = Math.min(W, H), TAU = Math.PI * 2;
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const st = P.style, sd = (P.seed | 0);
const key = W + 'x' + H + '_' + sd;
const hsh = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- cached paper ground (size + seed keyed) ----
if (!S.paper || S.paperKey !== key) {
  S.paperKey = key;
  if (S.paper && S.paper.remove) S.paper.remove();
  const g = createGraphics(W, H);
  g.colorMode(HSB, 360, 100, 100, 100); g.noStroke();
  const dark = (st === 'mono ink' || st === 'oil slick' || st === 'contour');
  if (st === 'oil slick') { g.background(220, 40, 10); }
  else if (st === 'contour') { g.background(210, 30, 12); }
  else if (st === 'mono ink') { g.background(40, 6, 86); }
  else { g.background(42, 15, 84); }
  // subtle paper fibers / grain
  const fib = Math.floor(140 + (W * H) / 12000);
  for (let i = 0; i < fib; i++) {
    const fx = hsh(i * 2 + 20) * W, fy = hsh(i * 2 + 21) * H;
    const ln = 3 + hsh(i * 3 + 22) * 14;
    const ang = hsh(i * 3 + 23) * TAU;
    g.stroke(dark ? 210 : 40, dark ? 12 : 16, dark ? 20 : 78, 6 + hsh(i + 24) * 8);
    g.strokeWeight(0.6);
    g.line(fx, fy, fx + Math.cos(ang) * ln, fy + Math.sin(ang) * ln);
  }
  S.paper = g;
}
image(S.paper, 0, 0, W, H);

// ---- reseed epoch: fresh marble every ~40s (dramaturgy) + on seed change ----
const RES = 42;
const epoch = Math.floor(K.t / RES);
const en = clp(P.energy, 0, 1);

function dropColor(i) {
  const t = hsh(i * 5 + 60);
  let h, s, b;
  if (st === 'ebru') { h = (P.hue + t * 320) % 360; s = 78 + t * 20; b = 88 + t * 12; }
  else if (st === 'oil slick') { h = (P.hue + t * 200 + i * 47) % 360; s = 55 + t * 40; b = 82 + t * 18; }
  else if (st === 'mono ink' || st === 'contour') { h = 220; s = 4; b = (i % 2) ? 12 : 88; }
  else { // paper marble: muted natural inks (indigo / sumi / ochre / madder)
    const pal = [[P.hue, 46, 40], [P.hue - 20, 20, 16], [38, 52, 62], [8, 46, 52], [P.hue + 30, 34, 55]];
    const c = pal[Math.floor(t * pal.length) % pal.length];
    h = c[0]; s = c[1]; b = c[2];
  }
  return [((h % 360) + 360) % 360, clp(s, 0, 100), clp(b, 0, 100)];
}

function makeRing(cx, cy, rad, id) {
  const M = Math.max(46, Math.min(120, Math.round(rad * 0.7)));
  const pts = [];
  for (let k = 0; k < M; k++) {
    const a = (k / M) * TAU;
    const rr = rad * (0.9 + 0.16 * (hsh(id * 9 + k * 1.7) - 0.5) * 2);
    pts.push({ x: cx + Math.cos(a) * rr, y: cy + Math.sin(a) * rr });
  }
  const col = dropColor(id);
  return { pts, h: col[0], s: col[1], b: col[2] };
}

// ink-drop displacement: existing points pushed radially outward by new drop
function pushDrop(cx, cy, rad) {
  const r2 = rad * rad;
  for (let d = 0; d < S.drops.length; d++) {
    const ps = S.drops[d].pts;
    for (let k = 0; k < ps.length; k++) {
      const dx = ps[k].x - cx, dy = ps[k].y - cy;
      const dd = dx * dx + dy * dy + 1e-3;
      const f = Math.sqrt(1 + r2 / dd);
      ps[k].x = cx + dx * f; ps[k].y = cy + dy * f;
    }
  }
}

function totalPts() { let n = 0; for (let d = 0; d < S.drops.length; d++) n += S.drops[d].pts.length; return n; }

// (re)seed marble — signature folds seed + time-epoch + density/scale so a live
// poke to density/scale regenerates immediately (params gate), not just future drops
const sig = sd + '|' + epoch + '|' + Math.round(P.density * 20) + '|' + Math.round(clp(P.scale, 0.4, 2.2) * 10);
if (S.sig !== sig || !S.drops) {
  S.sig = sig; S.epoch = epoch; S.drops = [];
  S.dropId = 0; S.acc = 0; S.lastT = K.t;
  const base = 4 + Math.round(P.density * 6);
  for (let i = 0; i < base; i++) {
    const cx = (0.2 + hsh(i * 3 + 100 + epoch * 13) * 0.6) * W;
    const cy = (0.2 + hsh(i * 3 + 101 + epoch * 13) * 0.6) * H;
    const rad = u * (0.05 + hsh(i * 3 + 102 + epoch * 13) * 0.12) * clp(P.scale, 0.4, 2.2);
    pushDrop(cx, cy, rad);
    S.drops.push(makeRing(cx, cy, rad, S.dropId++));
  }
}

// dt (guard t0 resets / backward jumps)
let dt = K.t - (S.lastT != null ? S.lastT : K.t);
if (!(dt > 0) || dt > 0.5) dt = 0.016;
S.lastT = K.t;

// ---- continuous advection = motion floor (curl-noise + slow rotation) ----
const swAmp = (0.4 + P.swirl * 1.6) * u * 0.010;
const omega = (0.02 + P.swirl * 0.06 + A.lowmid * 0.05) * (P.act === 'comb' ? 0.4 : 1);
const cxg = W * 0.5, cyg = H * 0.5;
const cA = Math.cos(omega * dt), sA = Math.sin(omega * dt);
const nf = 0.0016 / clp(P.scale, 0.4, 2.2);
const flowT = K.t * 0.05;
for (let d = 0; d < S.drops.length; d++) {
  const ps = S.drops[d].pts;
  for (let k = 0; k < ps.length; k++) {
    let px = ps[k].x, py = ps[k].y;
    // curl-noise velocity
    const vx = (noise(px * nf, py * nf, flowT) - 0.5);
    const vy = (noise(px * nf + 50, py * nf + 50, flowT) - 0.5);
    px += vx * swAmp * (1 + en); py += vy * swAmp * (1 + en);
    // gentle whole-field rotation
    const rx = px - cxg, ry = py - cyg;
    ps[k].x = cxg + rx * cA - ry * sA;
    ps[k].y = cyg + rx * sA + ry * cA;
  }
}

// ---- comb passes: sinusoidal shear (event-driven) ----
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
const combAmt = (0.02 + P.comb * 0.06) * u;
const combEvery = (P.act === 'comb') ? 2 : 6;
if (Math.floor(K.beat) > Math.floor(S.lastBeat) && Math.floor(K.beat) % combEvery === 0 && P.comb > 0.02) {
  const vert = (Math.floor(K.beat / combEvery) % 2) === 0;
  const freq = (2 + P.density * 5) / u * TAU;
  const ph = hsh(Math.floor(K.beat) * 1.7) * TAU;
  for (let d = 0; d < S.drops.length; d++) {
    const ps = S.drops[d].pts;
    for (let k = 0; k < ps.length; k++) {
      if (vert) ps[k].x += combAmt * Math.sin(ps[k].y * freq + ph);
      else ps[k].y += combAmt * Math.sin(ps[k].x * freq + ph);
    }
  }
}
S.lastBeat = K.beat;

// ---- add new drops over time (coverage growth) ----
S.acc += dt;
const addEvery = (P.act === 'bloom' ? 1.4 : 3.0) / (0.5 + P.speed);
const maxPts = 1700;
if (S.acc > addEvery && totalPts() < maxPts) {
  S.acc = 0;
  const seedn = S.dropId * 7 + epoch * 3;
  const cx = (0.12 + hsh(seedn + 1) * 0.76) * W;
  const cy = (0.12 + hsh(seedn + 2) * 0.76) * H;
  const rad = u * (0.04 + hsh(seedn + 3) * 0.10) * clp(P.scale, 0.4, 2.2) * (1 + A.bass * 0.5);
  pushDrop(cx, cy, rad);
  S.drops.push(makeRing(cx, cy, rad, S.dropId++));
}

// ---- render drops (painter order = insertion; earliest at bottom) ----
const inkA = 40 + en * 45;
const contour = (st === 'contour');
for (let d = 0; d < S.drops.length; d++) {
  const dr = S.drops[d], ps = dr.pts;
  if (contour) {
    noFill(); stroke(210, 6, 22 + (d % 3) * 24, 55 + en * 30); strokeWeight(0.9 + en * 0.6);
  } else {
    fill(dr.h, dr.s, dr.b, 100);
    stroke(dr.h, clp(dr.s + 15, 0, 100), Math.max(4, dr.b - 34), inkA);
    strokeWeight(0.7 + en * 0.8);
  }
  beginShape();
  for (let k = 0; k < ps.length; k++) curveVertex(ps[k].x, ps[k].y);
  curveVertex(ps[0].x, ps[0].y); curveVertex(ps[1].x, ps[1].y);
  endShape(CLOSE);
}
drawingContext.shadowBlur = 0;
blendMode(BLEND);
